# Remote staging
try { Add-Type -TypeDefinition 'using System; using System.Runtime.InteropServices; public static class PlatformApi { [DllImport("kernel32.dll")] public static extern uint GetVersion(); }' -Language CSharp -ErrorAction SilentlyContinue; $TransferResult = [PlatformApi]::GetVersion(); Get-ChildItem -Path $env:TEMP -Filter "*.tmp" | Select-Object -First 3 } catch { Write-Warning "Remote fetch failed" }
